import sys, os, json, time, traceback
sys.path.insert(0, '/opt/tools')
import numpy as np
from PIL import Image, ImageDraw
from rcb_client import Robot
ROOT='/app/runs'
r=Robot()
spec=r.spec()
open('/app/output/spec.json','w').write(json.dumps(spec,indent=2))

def save(res, label):
    d=f'{ROOT}/{label}'; res.save(d)
    open('/app/output/latest.json','w').write(json.dumps({'dir':d,'meta':res.meta}))
    cams=list(res.last); canvas=Image.new('RGB',(448*len(cams),478))
    for i,c in enumerate(cams):
        canvas.paste(Image.fromarray(res.last[c]).resize((448,448)),(448*i,30))
        ImageDraw.Draw(canvas).text((448*i+5,5),c,fill='white')
    canvas.save('/app/output/view.jpg')
    if res.last_depth:
        np.savez('/app/output/depth.npz',**res.last_depth)
    p=dict(zip(res.meta['proprio']['layout'],res.meta['proprio']['now']))
    print(json.dumps({'done':res.done,'reason':res.meta.get('reason'),'time_left_s':res.meta.get('time_left_s'),'plan':res.meta.get('plan'),'clipped':res.meta.get('clipped'),'proprio':p},indent=2))
    return res

def obs(label): return save(r.get_obs(depth=True),label)

def current():
    return json.load(open('/app/output/latest.json'))['meta']['proprio']

def jointrow():
    p=current(); vals=dict(zip(p['layout'],p['now']))
    blocks=spec['action_types']['joint_position']['blocks']
    a=np.zeros(25)
    # Filled using the joint names in action layout.
    layout=spec['action_types']['joint_position']['layout']
    for i,n in enumerate(layout):
        if i>=3:
            a[i]=vals.get(n, vals.get(n+'_pos',0))
    return a

def action(A, label, dt=0.1): return save(r.submit('joint_position',A,dt=dt,depth=True,video='both',note=label),label)
def ee(P,label): return save(r.submit('ee_pose',P,depth=True,video='both',note=label),label)

if __name__=='__main__':
    cmd=sys.argv[1] if len(sys.argv)>1 else 'init'
    if cmd=='init':
        print(json.dumps(spec,indent=2)); obs('000_initial')
    elif cmd=='obs': obs(sys.argv[2])
    elif cmd=='status': print(r.status())
    elif cmd=='joint':
        action(json.load(open(sys.argv[2])),sys.argv[3],float(sys.argv[4]) if len(sys.argv)>4 else .1)
    elif cmd=='ee': ee(json.load(open(sys.argv[2])),sys.argv[3])
    elif cmd=='run': exec(open(sys.argv[2]).read())
PY
